"""Original pituitary chapter: sellar evaluation and prolactin disorders."""
from qbank_authoring import question,ref,finalize
IN=ref('Pituitary Society: Pituitary Incidentaloma Consensus, 2025','https://www.nature.com/articles/s41574-025-01134-8')
PR=ref('Pituitary Society: Prolactinoma Consensus, 2023','https://www.nature.com/articles/s41574-023-00886-5.pdf')
HP=ref('Endocrine Society: Hormonal Replacement in Hypopituitarism, 2016','https://academic.oup.com/jcem/article/101/11/3888/2764912')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A 13-mm sellar lesion is found incidentally on a CT performed after trauma. What is the best initial evaluation?', 'Dedicated pituitary MRI plus assessment for hormone excess, pituitary deficiency and visual risk',[
 ('Assume every incidental lesion is nonfunctioning and discharge','Hormonal and compressive disease can be clinically subtle.'),('Proceed directly to surgery without defining anatomy or function','Treatment depends on the lesion and its consequences.'),('Measure only prolactin and ignore other axes','Other excess and deficiency states need consideration.')],
 'Incidental discovery does not establish biological inactivity', '**Dedicated imaging defines the lesion and its relation to the optic apparatus.**',['History and testing assess secretory syndromes and pituitary reserve.','Macroadenomas can cause deficiency without dramatic symptoms.'], '**Use multidisciplinary assessment according to risk.**',['The 2025 consensus individualizes surveillance and surgery decisions.','Do not treat all microlesions and macrolesions identically.'],[['Anatomy','Pituitary MRI'],['Function','Excess and deficiency evaluation'],['Compression','Visual and neurological assessment']],[IN],'clinical_scenario')
q('A pituitary mass abuts the optic chiasm but the patient reports normal vision. What assessment is indicated?', 'Formal visual field testing',[
 ('No testing until the patient notices blindness','Field loss can be subtle or unrecognized.'),('Visual acuity alone fully excludes chiasmal dysfunction','Peripheral field defects can occur with preserved central acuity.'),('An audiogram as the primary chiasmal test','This does not assess the optic pathway.')],
 'Anatomical proximity can matter before subjective symptoms', '**Chiasmal compression can produce bitemporal field loss.**',['The 2025 consensus also considers visual testing for macroincidentalomas and smaller near-chiasmal lesions.','The full ocular examination may add useful information.'], '**Coordinate timely neurosurgical and ophthalmic review when indicated.**',['Progression or objective deficit affects intervention decisions.','Document a baseline for follow-up.'],[['Compression target','Optic chiasm'],['Classic defect','Bitemporal field loss'],['Test','Formal perimetry']],[IN],'clinical_scenario')
q('A stable 5-mm nonfunctioning-appearing pituitary lesion is remote from the chiasm with normal hormonal assessment. Which management principle is appropriate?', 'Individualized surveillance rather than automatic surgery',[
 ('Every microincidentaloma requires urgent resection','Risk and functional assessment guide treatment.'),('No future review is ever needed in any small lesion','Surveillance depends on lesion type and clinical context.'),('Dopamine agonists are required for all nonfunctioning lesions','They are not universal treatment for every sellar incidentaloma.')],
 'Size, behavior, function and location determine risk', '**Small asymptomatic lesions often permit observation.**',['Cystic and adenomatous lesions can have different pathways.','New endocrine or visual symptoms require reassessment.'], '**Use the current consensus to select imaging intervals.**',['Avoid a one-size-fits-all annual imaging rule.','Patient age, prior growth and distance from the chiasm matter.'],[['Small stable lesion','Often observation'],['Growth or dysfunction','Reassess'],['Follow-up','Risk based']],[IN],'clinical_scenario')
q('An adult has modest prolactin elevation after starting risperidone. Which action is appropriate before assuming a prolactinoma?', 'Review the drug and clinical context, with repeat or targeted endocrine evaluation as needed',[
 ('Stop antipsychotic therapy abruptly without psychiatric input','This can cause serious relapse.'),('A single modest result proves a pituitary tumor','Drugs, stress and systemic conditions can raise prolactin.'),('Begin high-dose cabergoline automatically in every case','The psychiatric and endocrine risks require coordinated assessment.')],
 'Dopamine blockade removes tonic inhibition of prolactin', '**Antipsychotics are important causes of hyperprolactinemia.**',['Pregnancy, hypothyroidism and kidney impairment are additional considerations.','The magnitude and symptoms help determine further investigation.'], '**Coordinate any medication change with the treating clinician.**',['Do not ignore a large mass or neurological symptoms because a drug is present.','Treatment of a verified prolactinoma may still be needed.'],[['Mechanism','Dopamine antagonism'],['Evaluation','Medication and systemic causes'],['Safety','Joint psychiatric/endocrine plan']],[PR],'clinical_scenario')
q('A nonfunctioning sellar mass causes moderate hyperprolactinemia. Which mechanism explains the stalk effect?', 'Interruption of hypothalamic dopamine delivery to lactotrophs',[
 ('Increased tonic dopamine inhibition','Loss rather than excess of inhibition raises prolactin.'),('Direct proof that every cell in the mass secretes prolactin','Stalk compression can raise prolactin without a prolactinoma.'),('Loss of thyroid-binding globulin','This does not explain the prolactin mechanism.')],
 'Prolactin is normally under tonic inhibitory control', '**Dopamine reaches lactotrophs through the pituitary portal circulation.**',['Stalk disruption releases that inhibition.','A prolactin level must be interpreted with tumor size, drugs and assay behavior.'], '**Distinguish stalk effect from a true prolactinoma.**',['The distinction changes the expected response and management.','Exclude a hook effect when a large lesion has unexpectedly modest prolactin.'],[['Normal control','Dopamine inhibition'],['Stalk lesion','Reduced dopamine delivery'],['Result','Disinhibited prolactin secretion']],[PR])
q('A 4-cm pituitary mass is associated with only mildly elevated measured prolactin despite strong clinical suspicion for prolactinoma. What laboratory step is important?', 'Repeat prolactin using appropriate serial dilution to exclude a high-dose hook effect',[
 ('Assume the assay is linear at every concentration','Extreme antigen excess can distort some sandwich assays.'),('Diagnose a nonfunctioning tumor solely from the undiluted value','The apparent low value may be misleading.'),('Measure only macroprolactin without addressing antigen excess','Macroprolactin testing answers a different question.')],
 'A very high true concentration can paradoxically read low', '**Antigen excess can interfere with sandwich immunoassay formation.**',['Modern assays vary in susceptibility.','Communication with the laboratory is essential.'], '**Resolve the size-biochemistry mismatch before treatment selection.**',['Correct recognition can avoid unnecessary surgery.','Interpret the diluted result with the full clinical picture.'],[['Clue','Large mass/modest reported prolactin'],['Problem','High-dose hook effect'],['Solution','Appropriate dilution']],[PR],'clinical_scenario')
q('An asymptomatic person repeatedly has raised total prolactin but normal gonadal function. Which laboratory issue should be assessed?', 'Macroprolactin',[
 ('A hook effect is the only possible explanation for any high result','The hook effect usually produces an unexpectedly low result in extreme excess.'),('All measured prolactin is equally bioactive','Macroprolactin can contribute substantially to an assay result.'),('The result automatically requires long-term dopamine agonist therapy','Biological relevance and monomeric prolactin need clarification.')],
 'Immunoreactivity does not always equal clinical activity', '**Macroprolactin is often a prolactin-immunoglobulin complex with reduced biological activity.**',['Polyethylene glycol precipitation is a common screening method.','Clinically important monomeric hyperprolactinemia can coexist.'], '**Interpret the post-processing result with symptoms and the assay.**',['Avoid unnecessary imaging or treatment for isolated benign assay-detected excess.','Do not dismiss a symptomatic patient without assessing the active fraction.'],[['Assay result','May include macroprolactin'],['Clinical clue','Disproportionately few symptoms'],['Assessment','Monomeric fraction and context']],[PR],'clinical_scenario')
q('Hyperprolactinemia accompanies high TSH and low free T4. Which mechanism can account for the prolactin rise?', 'Increased hypothalamic TRH drive in primary hypothyroidism',[
 ('A suppressed TRH signal necessarily causes lactotroph stimulation','Primary thyroid failure increases TRH drive.'),('The thyroid results prove central hypothyroidism','High TSH with low free T4 usually indicates primary failure.'),('A prolactinoma is the only explanation despite untreated primary thyroid disease','Thyroid failure is a recognized secondary cause.')],
 'Systemic endocrine disease can mimic a primary pituitary secretory problem', '**TRH can stimulate prolactin secretion.**',['Severe longstanding primary hypothyroidism can also produce pituitary hyperplasia.','A true sellar tumor may occasionally coexist.'], '**Treat thyroid deficiency and reassess appropriately.**',['Avoid assuming pituitary surgery is needed before resolving the mechanism.','Urgent visual or other mass-effect findings still need timely assessment.'],[['Primary thyroid failure','Low T4/high TSH'],['Hypothalamic response','Increased TRH'],['Prolactin','Can rise secondarily']],[PR,HP])
q('A symptomatic macroprolactinoma has no immediate surgical emergency. Which medical therapy is commonly preferred?', 'Cabergoline',[
 ('Octreotide as the usual first prolactin-directed agent','Somatostatin analogs are chiefly used for other pituitary secretory contexts.'),('Levothyroxine regardless of thyroid status','It treats thyroid deficiency, not a confirmed prolactinoma itself.'),('Desmopressin','It treats AVP deficiency rather than prolactin excess.')],
 'Dopamine agonism can control secretion and shrink the tumor', '**Cabergoline is generally effective and well tolerated.**',['Bromocriptine remains an alternative in suitable contexts.','Surgery is also a legitimate option for selected patients under the 2023 consensus.'], '**Monitor prolactin, tumor response and symptoms.**',['Assess adverse effects and pituitary recovery.','Visual compromise requires timely specialist management rather than casual outpatient delay.'],[['Drug target','Dopamine D2 receptor'],['Effects','Prolactin reduction and tumor shrinkage'],['Monitoring','Biochemistry, anatomy and tolerance']],[PR],'clinical_scenario')
q('A patient with a well-circumscribed small prolactinoma prefers definitive treatment and has access to an experienced pituitary surgeon. Which statement reflects the 2023 consensus?', 'Surgery can be discussed as a first-line alternative in selected favorable cases',[
 ('Surgery is forbidden until every dopamine agonist has failed','The consensus supports shared first-line discussion in selected cases.'),('Every invasive giant prolactinoma has the same surgical cure probability','Anatomy and invasiveness materially affect outcomes.'),('Surgery eliminates all need for endocrine follow-up','Recurrence and pituitary function still need monitoring.')],
 'First-line choice can be individualized', '**Dopamine agonists remain a major effective option.**',['Expert surgery can be suitable for selected noninvasive lesions.','Patient preference, cure probability and complication risk all matter.'], '**Use an experienced multidisciplinary center.**',['Do not extrapolate favorable microadenoma outcomes to invasive disease.','Discuss the possibility of persistent or recurrent disease.'],[['Medical option','Dopamine agonist'],['Surgical option','Selected favorable anatomy'],['Decision','Expertise and informed preference']],[PR])
q('A patient treated with cabergoline develops new compulsive gambling and hypersexuality. What is the best interpretation?', 'A possible dopamine-agonist-associated impulse-control disorder',[
 ('This cannot be medication related at prolactinoma doses','Such effects can occur and need recognition.'),('The symptoms prove worsening tumor compression','The behavioral pattern suggests a drug effect among other causes.'),('Increase cabergoline automatically because behavior reflects low dopamine','This can worsen the problem.')],
 'Ask about behavioral adverse effects directly', '**Dopamine agonists can cause impulse-control symptoms.**',['Patients or families may not volunteer them.','Orthostatic and gastrointestinal effects are additional tolerability issues.'], '**Review the treatment promptly with the pituitary team.**',['Dose reduction, withdrawal or alternative therapy may be needed.','Assess psychiatric safety and support without blame.'],[['Exposure','Dopamine agonist'],['Symptoms','Compulsive reward-seeking behavior'],['Response','Prompt regimen and safety review']],[PR],'clinical_scenario')
q('A person with a treated macroprolactinoma becomes pregnant. Which monitoring statement is correct?', 'Clinical and visual assessment guide concern for tumor growth; routine prolactin levels are not a reliable growth marker in pregnancy',[
 ('A physiological pregnancy prolactin rise proves tumor enlargement','Prolactin rises normally and is not a reliable serial growth measure.'),('No visual symptoms matter during pregnancy','New headache or visual change requires assessment.'),('Every pregnancy requires routine gadolinium MRI regardless of symptoms','Imaging is individualized and contrast is generally avoided when unnecessary.')],
 'Pregnancy changes both physiology and tumor-risk management', '**Management depends on tumor size, invasiveness and prior control.**',['Many patients discontinue dopamine agonists after pregnancy confirmation, while selected high-risk cases may continue.','Symptomatic suspected growth warrants specialist visual and imaging evaluation.'], '**Plan pregnancy with the pituitary team.**',['Use MRI without gadolinium when indicated.','Do not apply a single medication rule to every micro- and macroprolactinoma.'],[['Prolactin during pregnancy','Poor growth marker'],['Warning signs','New headache or visual change'],['Treatment','Risk-based specialist plan']],[PR],'clinical_scenario')
q('When can dopamine-agonist withdrawal be considered in a prolactinoma?', 'After sustained biochemical control and favorable tumor response in a carefully selected patient with follow-up',[
 ('Immediately after the first normal prolactin in every patient','Durability and tumor factors matter.'),('Never under any circumstances','Selected patients can attempt withdrawal.'),('Only if follow-up is permanently discontinued','Recurrence surveillance is essential.')],
 'Withdrawal is a monitored trial rather than proof of cure', '**Favorable factors include low maintenance dose, prolonged control and marked or absent residual tumor.**',['A treatment duration of at least two years is often part of selection.','Recurrence remains possible.'], '**Plan serial prolactin and clinical review.**',['Restart or revise treatment when indicated.','Discuss symptoms and reproductive implications of recurrence.'],[['Selection','Sustained control/favorable anatomy'],['Attempt','Supervised withdrawal'],['Afterward','Recurrence monitoring']],[PR])
q('Clear unilateral rhinorrhea develops after rapid shrinkage of a large invasive prolactinoma on cabergoline. What complication needs urgent evaluation?', 'Cerebrospinal fluid leak',[
 ('Assume simple allergy and continue without assessment','A previously plugged skull-base defect can become exposed.'),('This proves successful treatment requires no further review','Tumor shrinkage can reveal a serious structural complication.'),('Treat solely by increasing the dopamine agonist dose','The leak requires specialist assessment.')],
 'A beneficial tumor response can unmask a skull-base defect', '**CSF rhinorrhea creates a risk of meningitis.**',['Large invasive tumors can erode the sellar floor.','Fluid testing and imaging help confirm the diagnosis.'], '**Arrange urgent pituitary and skull-base specialist review.**',['Do not dismiss the timing after shrinkage.','Management may require repair and adjustment of the tumor-treatment plan.'],[['Setting','Invasive tumor shrinking'],['Symptom','Clear rhinorrhea'],['Risk','CSF leak and infection']],[PR],'clinical_scenario')
q('Prolactin remains elevated during prescribed cabergoline treatment. What should be reviewed before labeling true dopamine-agonist resistance?', 'Adherence, dose, assay interpretation, tumor response and alternative causes of prolactin elevation',[
 ('Any single abnormal result proves permanent resistance','Exposure and diagnostic factors can explain nonresponse.'),('Escalate without checking tolerance or cumulative safety','Dose decisions require a monitored specialist plan.'),('Ignore imaging if prolactin is the only measured endpoint','Biochemical and structural responses can differ.')],
 'Resistance is a clinical and biochemical assessment', '**Some patients respond partially or require higher specialist-supervised doses.**',['Interacting drugs and macroprolactin can complicate interpretation.','Surgery or other treatment can be appropriate in genuine resistant disease.'], '**Evaluate the reason for apparent failure first.**',['Check symptoms, visual risk and pituitary function.','Use a multidisciplinary plan rather than endless unreviewed escalation.'],[['Before resistance label','Confirm exposure and diagnosis'],['Response domains','Hormone and tumor'],['Alternatives','Expert dose adjustment or surgery']],[PR])
q('Why does prolactin excess commonly cause amenorrhea or low testosterone?', 'Suppression of hypothalamic GnRH and downstream gonadotropin function',[
 ('Direct destruction of every gonad in all patients','The main common mechanism is central suppression.'),('Autonomous excess of LH and FSH','Gonadotropin drive is often reduced or inappropriate.'),('Obligate primary thyroid failure','Thyroid disease can be a cause of prolactin elevation but is not required for this mechanism.')],
 'A secretory disorder can create secondary hormone deficiency', '**Hyperprolactinemia impairs the reproductive axis.**',['Galactorrhea is not present in every affected person.','Bone effects can follow prolonged hypogonadism.'], '**Assess reproductive goals and duration of deficiency.**',['Treat the cause of prolactin excess where appropriate.','Monitor recovery rather than assuming permanent gonadal failure.'],[['Primary disturbance','Prolactin excess'],['Central effect','Reduced GnRH/gonadotropin drive'],['Consequences','Hypogonadism and reproductive dysfunction']],[PR,HP])
